<?php require __DIR__.'/_layout_start.php';$roles=['admin'=>'Amministratore completo','content'=>'Gestione contenuti','requests'=>'Gestione richieste']; ?><div class="toolbar"><div><h1>Utenti e accessi</h1><p class="page-lead">Amministratori, ruoli e ultimi accessi.</p></div><a class="btn" href="/idemaclima/admin/settings/users/form">Aggiungi utente</a></div><?php if($saved):?><p class="panel" style="border-color:#9acb70;background:#f3faed">Utente salvato correttamente.</p><?php endif;?><div class="table-wrap"><table><thead><tr><th>Utente</th><th>Email</th><th>Ruolo</th><th>Stato</th><th>Ultimo accesso</th><th></th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><strong><?= htmlspecialchars(trim($row['first_name'].' '.$row['last_name']),ENT_QUOTES,'UTF-8') ?></strong><br><span class="muted"><?= htmlspecialchars($row['username'],ENT_QUOTES,'UTF-8') ?></span></td><td><?= htmlspecialchars($row['email'],ENT_QUOTES,'UTF-8') ?></td><td><span class="badge"><?= htmlspecialchars($roles[$row['role']]??$row['role'],ENT_QUOTES,'UTF-8') ?></span></td><td><?= !empty($row['active'])?'Attivo':'Disabilitato' ?></td><td><?= !empty($row['last_login_at'])?htmlspecialchars(date('d/m/Y H:i',strtotime((string)$row['last_login_at'])),ENT_QUOTES,'UTF-8'):'Mai' ?></td><td><a href="/idemaclima/admin/settings/users/form?id=<?=(int)$row['id']?>">Modifica</a></td></tr><?php endforeach; ?></tbody></table></div><?php require __DIR__.'/_layout_end.php'; ?>
